#!/usr/bin/env python3
# SkillSwap Auth & Synchronization Fixer (Termux / Linux / macOS)
import os
import sys
import json
import base64

print('=' * 65)
print('SKILLSWAP: REPAIRING AUTHENTICATION & SYNC (TERMUX / GITHUB)')
print('=' * 65)

ROOT_DIR = os.path.abspath(os.path.dirname(__file__)) if '__file__' in globals() else os.getcwd()
os.chdir(ROOT_DIR)

PAYLOAD = ''

try:
    files_map = json.loads(base64.b64decode(PAYLOAD).decode('utf-8'))
    for rel_path, content in files_map.items():
        full_path = os.path.join(ROOT_DIR, rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        with open(full_path, 'w', encoding='utf-8') as f:
            f.write(content)
        print('   Updated ' + rel_path)
    
    print('')
    print('ALL AUTH & SYNC ISSUES HAVE BEEN FIXED SUCCESSFULLY!')
    print('=' * 65)
    print('Next steps to deploy to GitHub & Render:')
    print('   1. git add .')
    print('   2. git commit -m "fix: resolve authentication blocking, login mismatch, and Supabase sync"')
    print('   3. git push origin main')
    print('Render will automatically detect the commit, rebuild, and your live site will work!')
    print('=' * 65)
except Exception as e:
    print('Error applying fixes:', e)
    sys.exit(1)
